const fruitIcons = { L:"data:image/jpeg;base64,", EL:"data:image/jpeg;base64," };

// ==================================================
// わくわくの実ごとのアイコン
// ==================================================
const fruitTypeIcons = {
    "熱き友撃の力": "data:image/png;base64,",
    "同族の絆・加撃": "data:image/png;base64,",
    "同族の絆・加撃速": "data:image/png;base64,"
};

function getFruitIcon(fruit){
    if(!fruit) return "";
    const rawName = typeof fruit === "object" ? fruit.name : String(fruit);
    const name = String(rawName).replace(/\s+/g, "");
    const rankRaw = typeof fruit === "object" ? String(fruit.rank || "") : "";
    // L / EL の表記ゆれにも対応し、アイコンが必ず1つ表示されるようにする
    const rank = rankRaw.includes("EL") ? "EL" : (rankRaw.includes("L") ? "L" : "");
    const normalized = name.replace(/[・･\s]/g, "");

    // 「熱き友撃」「同族の絆・加撃」「同族の絆・加撃速」は、
    // 「同族の絆・加命撃」と同じランクアイコンを使用する。
    // （LならL、ELならEL）
    const sameIconAsKameigeki = [
        "熱き友撃の力",
        "同族の絆・加撃",
        "同族の絆・加撃速",
        "同族の絆・加命撃"
    ];
    const normalizedTargets = sameIconAsKameigeki.map(v => v.replace(/[・･\s]/g, ""));
    if (normalizedTargets.some(v => normalized === v || normalized.includes(v))) {
        return fruitIcons[rank] || fruitIcons.L || fruitIcons.EL || "";
    }

    if (fruitTypeIcons[rawName]) return fruitTypeIcons[rawName];
    if (fruitTypeIcons[name]) return fruitTypeIcons[name];
    // 個別アイコンがまだ登録されていない実は、ランクのアイコンを表示
    // ランク情報もない古いデータには L アイコンをフォールバックする
    return fruitIcons[rank] || fruitIcons.L || fruitIcons.EL || "";
}

function getFruitLabel(fruit){
    if(typeof fruit === "object") return `${fruit.name} ${fruit.rank}`;
    return fruit;
}

function iconHTML(src, alt, className="item-icon"){ return `<img class="${className}" src="${src}" alt="${alt}">`; }

