// PC・スマホ データ共有
// ==================================================

const exportDataBtn = document.getElementById("exportDataBtn");
const importDataBtn = document.getElementById("importDataBtn");
const shareDataBtn = document.getElementById("shareDataBtn");
const importDataFile = document.getElementById("importDataFile");

function getDataForTransfer(){
    return {
        app: "monster-data-manager",
        version: 1,
        exportedAt: new Date().toISOString(),
        accounts: accounts
    };
}

function downloadDataFile(){
    const data = JSON.stringify(getDataForTransfer(), null, 2);
    const blob = new Blob([data], {type:"application/json;charset=utf-8"});
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    const date = new Date().toISOString().slice(0,10);
    a.href = url;
    a.download = `モンスト管理データ_${date}.json`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function importDataObject(obj){
    if(!obj || obj.app !== "monster-data-manager" || !Array.isArray(obj.accounts)){
        throw new Error("このアプリのデータファイルではありません。");
    }

    const ok = confirm("現在のデータを、読み込むデータで置き換えます。続行しますか？");
    if(!ok) return;

    accounts = obj.accounts;
    saveData();
    currentAccountId = accounts.length ? accounts[0].id : null;
    loadData();
    alert("データを読み込みました。");
}

exportDataBtn?.addEventListener("click", downloadDataFile);

importDataBtn?.addEventListener("click", () => {
    importDataFile?.click();
});

importDataFile?.addEventListener("change", async (event) => {
    const file = event.target.files?.[0];
    if(!file) return;
    try{
        const text = await file.text();
        importDataObject(JSON.parse(text));
    }catch(error){
        alert("データの読み込みに失敗しました。正しいJSONファイルを選択してください。");
        console.error(error);
    }finally{
        event.target.value = "";
    }
});

shareDataBtn?.addEventListener("click", async () => {
    const data = JSON.stringify(getDataForTransfer(), null, 2);
    const file = new File([data], "モンスト管理データ.json", {type:"application/json"});

    try{
        if(navigator.share && (!navigator.canShare || navigator.canShare({files:[file]}))){
            await navigator.share({
                title: "モンスト管理データ",
                text: "モンスト管理アプリのデータです。",
                files: [file]
            });
            return;
        }
    }catch(error){
        if(error?.name === "AbortError") return;
        console.warn("Web Share API failed", error);
    }

    downloadDataFile();
    alert("共有機能に対応していないため、JSONファイルを書き出しました。ファイルをAirDrop等で送ってください。");
});
