function deleteAccount(id){

    const account =

        accounts.find(

            account =>

                account.id === id

        );

    if(!account){

        return;

    }

    if(

        !confirm(

            `「${account.name}」を削除しますか？`

        )

    ){

        return;

    }

    accounts =

        accounts.filter(

            account =>

                account.id !== id

        );

    if(

        currentAccountId === id

    ){

        if(accounts.length > 0){

            currentAccountId =

                accounts[0].id;

        }

        else{

            currentAccountId =

                null;

        }

    }

    saveData();

    updateAccountSelect();

    updateSearchAccount();

    displayTabs();

    displayCurrentAccount();

}

