// キャラ追加

// ==================================================

function addCharacter(){

    const accountId =

        Number(

            accountSelect.value

        );

    const name =

        characterName.value.trim();

    if(!accountId){

        alert(

            "アカウントを選択してください"

        );

        return;

    }

    if(name === ""){

        alert(

            "キャラ名を入力してください"

        );

        return;

    }

    const account =

        accounts.find(

            account =>

                account.id === accountId

        );

    if(!account){

        return;

    }

    /*

     * ここが今回の重要ポイント

     *

     * 所持数ではなく、

     * キャラ1体を1つのデータとして登録する。

     *

     * 同じ名前のキャラを何体でも登録できる。

     */

    const evolution = characterEvolution.value;

    const isKaOrAbove = isEvolutionKaOrAbove(evolution);

    account.characters.push({

        id: Date.now(),

        name: name,

        evolution: evolution,

        books: {
            greatHero: greatHeroBook.checked,
            hero: heroBook.checked,
            battle: isKaOrAbove ? false : battleBook.checked,
            level: isKaOrAbove ? false : levelBook.checked,
            connect: evolution === "獣神化・改" ? connectBook.checked : false
        },

        fruits: []

    });

    currentAccountId =

        accountId;

    saveData();

    characterName.value = "";
    characterEvolution.value = "進化前";
    greatHeroBook.checked = false;
    heroBook.checked = false;
    battleBook.checked = false;
    levelBook.checked = false;
    connectBook.checked = false;
    updateBookAvailability();

    displayTabs();

    displayCurrentAccount();

    updateFruitCharacterSelect();

}

// ==================================================
// 書の使用可否
// ==================================================

function isEvolutionKaOrAbove(evolution){
    return evolution === "獣神化・改" || evolution === "真・獣神化";
}

function updateBookAvailability(){
    const evolution = characterEvolution.value;
    const isKaOrAbove = isEvolutionKaOrAbove(evolution);
    const isKaOnly = evolution === "獣神化・改";

    battleBook.disabled = isKaOrAbove;
    levelBook.disabled = isKaOrAbove;
    connectBook.disabled = !isKaOnly;

    battleBookLabel.classList.toggle("disabled-book", isKaOrAbove);
    levelBookLabel.classList.toggle("disabled-book", isKaOrAbove);
    connectBookLabel.classList.toggle("disabled-book", !isKaOnly);

    if(isKaOrAbove){
        battleBook.checked = false;
        levelBook.checked = false;
    }
    if(!isKaOnly){
        connectBook.checked = false;
    }

    if(isKaOrAbove){
        bookNotice.textContent = isKaOnly
            ? "獣神化・改：コネクトスキルの書を選択できます。戦型の書・レベルの書は選択できません。"
            : "真・獣神化：戦型の書・レベルの書・コネクトスキルの書は選択できません。";
    } else {
        bookNotice.textContent = "";
    }
}

