// ==================================================

function editCharacter(

    accountId,

    characterId

){
    const account = accounts.find(account => account.id === accountId);
    if(!account) return;

    const character = account.characters.find(character => character.id === characterId);
    if(!character) return;

    editingAccountId = accountId;
    editingCharacterId = characterId;

    editCharacterNameInput.value = character.name || "";
    editCharacterEvolution.value = character.evolution || "進化前";

    const books = character.books || {};
    editGreatHeroBook.checked = !!books.greatHero;
    editHeroBook.checked = !!books.hero;
    editBattleBook.checked = !!books.battle;
    editLevelBook.checked = !!books.level;
    editConnectBook.checked = !!books.connect;

    setEditBookIcons();
    updateEditBookAvailability();
    characterEditModal.classList.add("open");
    characterEditModal.setAttribute("aria-hidden", "false");
    setTimeout(() => editCharacterNameInput.focus(), 0);
}

function setEditBookIcons(){
    const map = [
        ["editGreatHeroBookIcon", "greatHero", "大英雄の書"],
        ["editHeroBookIcon", "hero", "英雄の書"],
        ["editBattleBookIcon", "battle", "戦型の書"],
        ["editLevelBookIcon", "level", "レベルの書"],
        ["editConnectBookIcon", "connect", "コネクトスキルの書"]
    ];
    map.forEach(([id, key, label]) => {
        const el = document.getElementById(id);
        if(el) el.innerHTML = bookIcons[key] ? iconHTML(bookIcons[key], label, "edit-book-icon") : "";
    });
}

function updateEditBookAvailability(){
    const evolution = editCharacterEvolution.value;
    const isKaOrAbove = isEvolutionKaOrAbove(evolution);
    const isKaOnly = evolution === "獣神化・改";

    editBattleBook.disabled = isKaOrAbove;
    editLevelBook.disabled = isKaOrAbove;
    editConnectBook.disabled = !isKaOnly;
    editBattleBookLabel.classList.toggle("disabled-book", isKaOrAbove);
    editLevelBookLabel.classList.toggle("disabled-book", isKaOrAbove);
    editConnectBookLabel.classList.toggle("disabled-book", !isKaOnly);

    if(isKaOrAbove){
        editBattleBook.checked = false;
        editLevelBook.checked = false;
    }
    if(!isKaOnly) editConnectBook.checked = false;

    if(isKaOrAbove){
        editBookNotice.textContent = isKaOnly
            ? "獣神化・改：コネクトスキルの書を選択できます。戦型の書・レベルの書は選択できません。"
            : "真・獣神化：戦型の書・レベルの書・コネクトスキルの書は選択できません。";
    } else {
        editBookNotice.textContent = "";
    }
}

function closeCharacterEdit(){
    characterEditModal.classList.remove("open");
    characterEditModal.setAttribute("aria-hidden", "true");
    editingAccountId = null;
    editingCharacterId = null;
}

function saveCharacterEdit(){
    if(editingAccountId === null || editingCharacterId === null) return;
    const account = accounts.find(account => account.id === editingAccountId);
    if(!account) return;
    const character = account.characters.find(character => character.id === editingCharacterId);
    if(!character) return;

    const name = editCharacterNameInput.value.trim();
    if(name === ""){
        alert("キャラ名を空にはできません");
        return;
    }

    const evolution = editCharacterEvolution.value;
    const isKaOrAbove = isEvolutionKaOrAbove(evolution);
    const isKaOnly = evolution === "獣神化・改";

    character.name = name;
    character.evolution = evolution;
    character.books = {
        greatHero: !!editGreatHeroBook.checked,
        hero: !!editHeroBook.checked,
        battle: isKaOrAbove ? false : !!editBattleBook.checked,
        level: isKaOrAbove ? false : !!editLevelBook.checked,
        connect: isKaOnly ? !!editConnectBook.checked : false
    };

    saveData();
    closeCharacterEdit();
    displayCurrentAccount();
    updateFruitCharacterSelect();
    updateBulkFruitSlots();
}

