function getFruitSlotCount(character){
    if(!character) return 2;
    const books = character.books || {};
    if(books.greatHero) return 4;
    if(books.hero) return 3;
    return 2;
}

function getSelectedFruitCharacter(){
    const accountId = Number(fruitAccountSelect.value);
    const characterId = Number(fruitCharacterSelect.value);
    if(!accountId || !characterId) return null;
    const account = accounts.find(account => account.id === accountId);
    if(!account) return null;
    return account.characters.find(character => character.id === characterId) || null;
}

const fruitTabGroups = {
    "同族": fruitBaseList.filter(name => name.startsWith("同族の絆")),
    "撃種": fruitBaseList.filter(name => name.startsWith("撃種の絆")),
    "戦型": fruitBaseList.filter(name => name.startsWith("戦型の絆")),
    "その他": fruitBaseList.filter(name => !name.startsWith("同族の絆") && !name.startsWith("撃種の絆") && !name.startsWith("戦型の絆"))
};

function fruitKey(name){
    return String(name).replace(/[・･\s]/g, "");
}

function findSelectedFruit(character, name){
    if(!character || !Array.isArray(character.fruits)) return null;
    return character.fruits.find(f => {
        const n = typeof f === "object" ? f.name : f;
        return fruitKey(n) === fruitKey(name);
    }) || null;
}

function renderBulkFruitTabs(){
    bulkFruitTabs.innerHTML = "";
    Object.keys(fruitTabGroups).forEach(tabName => {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "bulk-fruit-tab" + (bulkFruitActiveTab === tabName ? " active" : "");
        button.textContent = tabName;
        button.addEventListener("click", () => {
            bulkFruitActiveTab = tabName;
            renderBulkFruitTabs();
            renderBulkFruitList();
        });
        bulkFruitTabs.appendChild(button);
    });
}

function getBulkSelections(){
    return { ...bulkFruitSelections };
}

function syncBulkFruitSelectionsFromCharacter(character){
    const key = character ? `${fruitAccountSelect.value}:${fruitCharacterSelect.value}` : null;
    if(key === bulkFruitSelectionCharacterKey) return;

    bulkFruitSelectionCharacterKey = key;
    bulkFruitSelections = {};
    if(character && Array.isArray(character.fruits)){
        character.fruits.forEach(f => {
            const name = typeof f === "object" ? f.name : f;
            const rank = typeof f === "object" ? (f.rank || "L") : "L";
            if(name) bulkFruitSelections[name] = rank;
        });
    }
}

function renderBulkFruitList(){
    bulkFruitList.innerHTML = "";
    const character = getSelectedFruitCharacter();
    if(!character){
        bulkFruitList.innerHTML = '<div class="bulk-fruit-empty">先にアカウントとキャラを選択してください。</div>';
        renderBulkFruitSelected();
        return;
    }
    syncBulkFruitSelectionsFromCharacter(character);
    const count = getFruitSlotCount(character);
    const existing = bulkFruitSelections;

    fruitTabGroups[bulkFruitActiveTab].forEach(name => {
        const row = document.createElement("label");
        row.className = "bulk-fruit-option";
        const check = document.createElement("input");
        check.type = "checkbox";
        check.className = "bulk-fruit-check";
        check.dataset.fruit = name;
        check.checked = Object.prototype.hasOwnProperty.call(existing, name);
        const label = document.createElement("span");
        label.className = "bulk-fruit-option-name";
        label.textContent = name;
        const rank = document.createElement("select");
        rank.className = "bulk-fruit-rank";
        rank.dataset.fruit = name;
        fruitRanks.forEach(r => {
            const option = document.createElement("option");
            option.value = r;
            option.textContent = r;
            rank.appendChild(option);
        });
        rank.value = existing[name] || "L";
        row.append(check, label, rank);
        bulkFruitList.appendChild(row);

        check.addEventListener("change", () => {
            if(check.checked){
                if(Object.keys(bulkFruitSelections).length >= count){
                    check.checked = false;
                    alert(`このキャラに登録できるわくわくの実は${count}個までです`);
                    return;
                }
                bulkFruitSelections[name] = rank.value || "L";
            }else{
                delete bulkFruitSelections[name];
            }
            renderBulkFruitSelected();
        });
        rank.addEventListener("change", () => {
            if(check.checked){
                bulkFruitSelections[name] = rank.value;
            }
            renderBulkFruitSelected();
        });
    });
    renderBulkFruitSelected();
}

function renderBulkFruitSelected(){
    const character = getSelectedFruitCharacter();
    const count = getFruitSlotCount(character);
    const selections = getBulkSelections();
    const entries = Object.entries(selections);
    bulkFruitSelected.innerHTML = "";
    entries.forEach(([name, rank]) => {
        const chip = document.createElement("div");
        chip.className = "bulk-fruit-selected-item";
        chip.innerHTML = `<span>${name} ${rank}</span>`;
        bulkFruitSelected.appendChild(chip);
    });
    bulkFruitSelectedCount.textContent = `${entries.length} / ${count}`;
    bulkFruitBtn.disabled = !character || entries.length === 0 || entries.length > count;
}

function updateBulkFruitSlots(){
    const character = getSelectedFruitCharacter();
    if(!character){
        bulkFruitSelectionCharacterKey = null;
        bulkFruitSelections = {};
        bulkFruitNotice.textContent = "キャラを選択すると、使用している書に応じた個数をまとめて選択できます。";
        bulkFruitBtn.disabled = true;
        renderBulkFruitTabs();
        renderBulkFruitList();
        return;
    }
    const count = getFruitSlotCount(character);
    const books = character.books || {};
    let reason = "どちらの書も未使用";
    if(books.greatHero) reason = "大英雄の書を使用中";
    else if(books.hero) reason = "英雄の書を使用中";
    bulkFruitNotice.textContent = `${reason}：最大${count}個まで、タブから複数の実を選んで一括登録できます。`;
    renderBulkFruitTabs();
    renderBulkFruitList();
}

function setFruitsInBulk(){
    const character = getSelectedFruitCharacter();
    if(!character){
        alert("アカウントとキャラを選択してください");
        return;
    }
    const selections = getBulkSelections();
    const fruits = Object.entries(selections).map(([name, rank]) => ({name, rank}));
    const max = getFruitSlotCount(character);
    if(fruits.length === 0){
        alert("登録するわくわくの実を1個以上選択してください");
        return;
    }
    if(fruits.length > max){
        alert(`このキャラに登録できるわくわくの実は${max}個までです`);
        return;
    }
    character.fruits = fruits;
    saveData();
    displayCurrentAccount();
    updateBulkFruitSlots();
    fruitName.value = "";
    fruitRank.value = "";
}

// ==================================================

// わくわくの実追加

// ==================================================

function addFruit(){

    const accountId =

        Number(

            fruitAccountSelect.value

        );

    const characterId =

        Number(

            fruitCharacterSelect.value

        );

    const fruit =

        fruitName.value;

    const rank =

        fruitRank.value;

    // ----------------------------

    // アカウント確認

    // ----------------------------

    if(!accountId){

        alert(

            "アカウントを選択してください"

        );

        return;

    }

    // ----------------------------

    // キャラ確認

    // ----------------------------

    if(!characterId){

        alert(

            "キャラを選択してください"

        );

        return;

    }

    // ----------------------------

    // 実確認

    // ----------------------------

    if(fruit === ""){

        alert(

            "わくわくの実を選択してください"

        );

        return;

    }

    // ----------------------------

    // 階級確認

    // ----------------------------

    if(rank === ""){

        alert(

            "階級を選択してください"

        );

        return;

    }

    const account =

        accounts.find(

            account =>

                account.id === accountId

        );

    if(!account){

        return;

    }

    /*

     * characterIdを使っているので、

     * 同じキャラ名でも別個体を

     * 完全に区別できる。

     */

    const character =

        account.characters.find(

            character =>

                character.id === characterId

        );

    if(!character){

        return;

    }

    if(!character.fruits){

        character.fruits = [];

    }

    // ----------------------------

    // 書に応じた個数制限

    // ----------------------------

    const maxFruits = getFruitSlotCount(character);

    if(character.fruits.length >= maxFruits){
        alert(`このキャラに登録できるわくわくの実は${maxFruits}個までです`);
        return;
    }

    // ----------------------------

    // 実を登録

    // ----------------------------

    character.fruits.push({

        name: fruit,

        rank: rank

    });

    saveData();

    fruitName.value = "";

    fruitRank.value = "";

    displayCurrentAccount();

}

// ==================================================

// わくわくの実削除

// ==================================================

function deleteFruit(

    accountId,

    characterId,

    fruitIndex

){

    const account =

        accounts.find(

            account =>

                account.id === accountId

        );

    if(!account){

        return;

    }

    const character =

        account.characters.find(

            character =>

                character.id === characterId

        );

    if(!character){

        return;

    }

    const fruit =

        character.fruits[

            fruitIndex

        ];

    if(!fruit){

        return;

    }

    let text;

    if(

        typeof fruit === "object"

    ){

        text =

            `${fruit.name} ${fruit.rank}`;

    }

    else{

        text =

            fruit;

    }

    if(

        !confirm(

            `「${text}」を削除しますか？`

        )

    ){

        return;

    }

    character.fruits.splice(

        fruitIndex,

        1

    );

    saveData();

    displayCurrentAccount();

}

