function bookSummaryHTML(character){
    const books = character.books || {};
    const items = [];
    const addBook = (key,label,allowed=true) => {
        if(books[key] && allowed) items.push(`<span class="book-item">${iconHTML(bookIcons[key],label,"book-item-icon")}<span>${label}</span></span>`);
    };
    addBook("greatHero","大英雄の書");
    addBook("hero","英雄の書");
    addBook("battle","戦型の書",!isEvolutionKaOrAbove(character.evolution));
    addBook("level","レベルの書",!isEvolutionKaOrAbove(character.evolution));
    addBook("connect","コネクトスキルの書",character.evolution === "獣神化・改");
    return items.length ? items.join(" ") : "なし";
}

// ==================================================
// アカウント詳細をTXT出力
// ==================================================
function exportCurrentAccountTxt(accountId){
    const account = accounts.find(a => a.id === accountId);
    if(!account) return;

    const lines = [];
    lines.push(`アカウント：${account.name}`);
    lines.push(`登録キャラ数：${account.characters.length}`);
    lines.push("");
    lines.push("========================================");
    lines.push("");

    account.characters.forEach((character, index) => {
        lines.push(`【キャラ ${index + 1}】`);
        lines.push(`キャラ名：${character.name}`);
        lines.push(`進化形態：${character.evolution || "進化前"}`);

        const books = character.books || {};
        const bookNames = [];
        if(books.greatHero) bookNames.push("大英雄の書");
        if(books.hero) bookNames.push("英雄の書");
        if(books.battle && !isEvolutionKaOrAbove(character.evolution)) bookNames.push("戦型の書");
        if(books.level && !isEvolutionKaOrAbove(character.evolution)) bookNames.push("レベルの書");
        if(books.connect && character.evolution === "獣神化・改") bookNames.push("コネクトスキルの書");
        lines.push(`使用している書：${bookNames.length ? bookNames.join("、") : "なし"}`);

        const fruits = Array.isArray(character.fruits) ? character.fruits : [];
        if(fruits.length){
            lines.push("わくわくの実：");
            fruits.forEach((fruit, fruitIndex) => {
                if(typeof fruit === "object" && fruit){
                    lines.push(`  ${fruitIndex + 1}. ${fruit.name || ""} ${fruit.rank || ""}`.trim());
                }else{
                    lines.push(`  ${fruitIndex + 1}. ${fruit}`);
                }
            });
        }else{
            lines.push("わくわくの実：なし");
        }
        lines.push("");
        lines.push("----------------------------------------");
        lines.push("");
    });

    const blob = new Blob(["\\uFEFF" + lines.join("\\n")], {type:"text/plain;charset=utf-8"});
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    const safeName = String(account.name || "account").replace(/[\\/:*?"<>|]/g, "_");
    a.href = url;
    a.download = `${safeName}_キャラ詳細.txt`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
}

