function displayCurrentAccount(){

    accountList.innerHTML = "";

    if(

        currentAccountId === null

    ){

        accountList.innerHTML =

            "<p>アカウントを選択してください。</p>";

        return;

    }

    const account =

        accounts.find(

            account =>

                account.id === currentAccountId

        );

    if(!account){

        return;

    }

    // ----------------------------

    // アカウントタイトル

    // ----------------------------

    let html = `

        <div class="account-title">

            <h2>

                ${account.name}

            </h2>

            <div class="account-title-buttons">
                <button
                    type="button"
                    onclick="exportCurrentAccountTxt(${account.id})"
                >
                    キャラ詳細をTXT出力
                </button>

                <button
                    class="delete"
                    onclick="
                        deleteAccount(
                            ${account.id}
                        )
                    "
                >
                    アカウント削除
                </button>
            </div>

        </div>

    `;

    // ----------------------------

    // キャラがない場合

    // ----------------------------

    if(

        account.characters.length === 0

    ){

        html += `

            <p>

                キャラが登録されていません。

            </p>

        `;

    }

    // ----------------------------

    // キャラ表示

    // ----------------------------

    account.characters.forEach(

        (

            character,

            index

        ) => {

            if(!character.fruits){

                character.fruits = [];

            }

            // ------------------------

            // 同じキャラの個体番号

            // ------------------------

            const sameCharacters =

                account.characters.filter(

                    c =>

                        c.name === character.name

                );

            let individualNumber = 1;

            for(

                let i = 0;

                i < index;

                i++

            ){

                if(

                    account.characters[i].name

                    === character.name

                ){

                    individualNumber++;

                }

            }

            let individualText = "";

            if(

                sameCharacters.length > 1

            ){

                individualText =

                    `個体${individualNumber}`;

            }

            // ------------------------

            // 実

            // ------------------------

            let fruitHTML = "";

            if(

                character.fruits.length > 0

            ){

                character.fruits.forEach(

                    (

                        fruit,

                        fruitIndex

                    ) => {

                        let fruitText;

                        if(

                            typeof fruit === "object"

                        ){

                            fruitText =

                                `${fruit.name} ${fruit.rank}`;

                        }

                        else{

                            fruitText =

                                fruit;

                        }

                        const fruitIcon = getFruitIcon(fruit);
                        fruitHTML += `

                            <span class="fruit-item">
                                ${fruitIcon ? `<img class="fruit-icon" src="${fruitIcon}" alt="">` : ""}
                                <span class="fruit-name">${fruitText}</span>
                                <button

                                    class="fruit-delete"

                                    onclick="

                                        deleteFruit(

                                            ${account.id},

                                            ${character.id},

                                            ${fruitIndex}

                                        )

                                    "

                                >

                                    ×

                                </button>

                            </span>

                        `;

                    }

                );

            }

            else{

                fruitHTML =

                    "なし";

            }

            // ------------------------

            // キャラ

            // ------------------------

            html += `

                <div class="character">

                    <span

                        class="character-number"

                    >

                        ${individualText}

                    </span>

                    ${character.image ? `
                        <img class="character-image" src="${character.image}" alt="${character.name}">
                    ` : ""}

                    <h3>

                        ${character.name}

                    </h3>

                    <p>
                        進化形態：${character.evolution || "進化前"}
                    </p>

                    <p>
                        所持数：1体
                    </p>

                    <p>
                        使用している書：${bookSummaryHTML(character)}
                    </p>

                    <p>

                        わくわくの実：

                    </p>

                    <div class="fruit-list">

                        ${fruitHTML}

                    </div>

                    <div

                        class="character-buttons"

                    >

                        <button

                            onclick="

                                editCharacter(

                                    ${account.id},

                                    ${character.id}

                                )

                            "

                        >

                            キャラ編集

                        </button>

                        <button

                            class="delete"

                            onclick="

                                deleteCharacter(

                                    ${account.id},

                                    ${character.id}

                                )

                            "

                        >

                            キャラ削除

                        </button>

                    </div>

                </div>

            `;

        }

    );

    accountList.innerHTML =

        html;

}

// ==================================================

// 検索

// ==================================================

function searchCharacters(){

    const keyword =

        searchBox.value

            .trim()

            .toLowerCase();

    const selectedAccount =

        searchAccount.value;

    if(keyword === ""){

        alert(

            "検索文字を入力してください"

        );

        return;

    }

    searchResult.innerHTML = "";

    let targetAccounts =

        accounts;

    // ----------------------------

    // アカウント指定

    // ----------------------------

    if(

        selectedAccount !== "all"

    ){

        targetAccounts =

            accounts.filter(

                account =>

                    String(account.id)

                    === selectedAccount

            );

    }

    let found = false;

    // ----------------------------

    // 検索

    // ----------------------------

    targetAccounts.forEach(

        account => {

            account.characters.forEach(

                (

                    character,

                    index

                ) => {

                    if(!character.fruits){

                        character.fruits = [];

                    }

                    const name =

                        character.name

                            .toLowerCase();

                    let fruitsText = "";

                    character.fruits.forEach(

                        fruit => {

                            if(

                                typeof fruit === "object"

                            ){

                                fruitsText +=

                                    " " +

                                    fruit.name +

                                    " " +

                                    fruit.rank;

                            }

                            else{

                                fruitsText +=

                                    " " +

                                    fruit;

                            }

                        }

                    );

                    fruitsText =

                        fruitsText.toLowerCase();

                    if(

                        name.includes(keyword) ||

                        fruitsText.includes(keyword)

                    ){

                        found = true;

                        // ------------------------

                        // 個体番号

                        // ------------------------

                        const sameCharacters =

                            account.characters.filter(

                                c =>

                                    c.name

                                    === character.name

                            );

                        let number = 1;

                        for(

                            let i = 0;

                            i < index;

                            i++

                        ){

                            if(

                                account.characters[i].name

                                === character.name

                            ){

                                number++;

                            }

                        }

                        let individualText = "";

                        if(

                            sameCharacters.length > 1

                        ){

                            individualText =

                                `個体${number}`;

                        }

                        // ------------------------

                        // 実

                        // ------------------------

                        let fruitHTML = "";

                        character.fruits.forEach(

                            (

                                fruit,

                                fruitIndex

                            ) => {

                                let fruitText;

                                if(

                                    typeof fruit === "object"

                                ){

                                    fruitText =

                                        `${fruit.name} ${fruit.rank}`;

                                }

                                else{

                                    fruitText =

                                        fruit;

                                }

                                const fruitIcon = getFruitIcon(fruit);
                                fruitHTML += `

                                    <span

                                        class="fruit-item"

                                    >
                                        ${fruitIcon ? `<img class="fruit-icon" src="${fruitIcon}" alt="">` : ""}
                                        <span class="fruit-name">${fruitText}</span>

                                        <button

                                            class="fruit-delete"

                                            onclick="

                                                deleteFruit(

                                                    ${account.id},

                                                    ${character.id},

                                                    ${fruitIndex}

                                                );

                                                searchCharacters();

                                            "

                                        >   
                                        
                                            x

                                        </button>

                                    </span>

                                `;

                            }

                        );

                        if(

                            fruitHTML === ""

                        ){

                            fruitHTML =

                                "なし";

                        }

                        // ------------------------

                        // 検索結果

                        // ------------------------

                        const div =

                            document.createElement(

                                "div"

                            );

                        div.className =

                            "character";

                        div.innerHTML = `

                            <p

                                class="search-account"

                            >

                                ${account.name}

                            </p>

                            <span

                                class="character-number"

                            >

                                ${individualText}

                            </span>

                            ${character.image ? `
                                <img class="character-image" src="${character.image}" alt="${character.name}">
                            ` : ""}

                            <h3>

                                ${character.name}

                            </h3>

                            <p>
                                進化形態：${character.evolution || "進化前"}
                            </p>

                            <p>
                                所持数：1体
                            </p>

                            <p>
                                使用している書：${bookSummaryHTML(character)}
                            </p>

                            <p>

                                わくわくの実：
                            </p>

                            <div class="fruit-list">

                                ${fruitHTML}

                            </div>

                            <button

                                onclick="

                                    editCharacter(

                                        ${account.id},

                                        ${character.id}

                                    );

                                    searchCharacters();

                                "

                            >

                                キャラ編集

                            </button>

                            <button

                                class="delete"

                                onclick="

                                    deleteCharacter(

                                        ${account.id},

                                        ${character.id}

                                    );

                                    searchCharacters();

                                "

                            >

                                キャラ削除

                            </button>

                        `;

                        searchResult.appendChild(

                            div

                        );

                    }

                }

            );

        }

    );

    if(!found){

        searchResult.innerHTML = `

            <p>

                「${searchBox.value}」

                に一致するキャラがありません。
            </p>

        `;

    }

}

